// Applied rules: [C8, III④]
// Skipped rules: [II_vec: Hits [0,1,2] arise from true CRC carry/state used after each loop; C8 is the structural fix. Applying II_vec directly to these loops would not remove the recurrence dependency and is subsumed by the CRC-specific rewrite.; III④: Did not target hits [4,5,6,7,8,9,10,11,12] separately because they are inside the hot 32-byte/4-byte word-processing core that C8 rewrites wholesale; standalone slice-ification there is lower-value and may interfere with unaligned word-load structure.]
unsafe fn crc32_little(
    mut crc: c_ulong,
    mut buf: *const c_uchar,
    mut len: z_size_t,
) -> c_ulong {
    let mut c: z_crc_t = crc as z_crc_t;
    static mut S8: [[z_crc_t; 256]; 8] = [[0; 256]; 8];
    static mut S8_INIT: bool = false;

    if !S8_INIT {
        let mut i: usize = 0;
        while i < 256 {
            S8[0][i] = crc_table[0][i];
            i += 1;
        }
        let mut s: usize = 1;
        while s < 8 {
            let mut j: usize = 0;
            while j < 256 {
                let prev = S8[s - 1][j];
                S8[s][j] = (prev >> 8) ^ S8[0][(prev & 0xff) as usize];
                j += 1;
            }
            s += 1;
        }
        S8_INIT = true;
    }

    c = !c;

    if len != 0 {
        let prefix = len;
        // SAFETY: `buf` is the caller-provided input pointer for `len` bytes; this
        // local shared slice is used only for the surviving bytewise prefix/tail walks,
        // does not outlive the region, and no mutable references are created.
        let bytes = unsafe { core::slice::from_raw_parts(buf, prefix) };
        let mut consumed: usize = 0;
        while consumed < bytes.len() && (buf as ptrdiff_t & 3 as ptrdiff_t) != 0 {
            c = crc_table[0][((c as c_uint ^ bytes[consumed] as c_uint) & 0xff) as usize] ^ c >> 8;
            buf = buf.offset(1);
            len = len.wrapping_sub(1);
            consumed += 1;
        }
    }

    while len >= 8 as z_size_t {
        let one = {
            // SAFETY: `buf` points to at least 8 remaining bytes here; unaligned 32-bit
            // loads are required and `read_unaligned` is used accordingly.
            unsafe { (buf as *const u32).read_unaligned() ^ c as u32 }
        };
        let two = {
            // SAFETY: `buf.add(4)` is within the same 8-byte chunk proven available by
            // `len >= 8`; unaligned 32-bit loads are required and `read_unaligned` is used.
            unsafe { (buf.offset(4) as *const u32).read_unaligned() }
        };
        c = S8[7][(one & 0xff) as usize]
            ^ S8[6][((one >> 8) & 0xff) as usize]
            ^ S8[5][((one >> 16) & 0xff) as usize]
            ^ S8[4][(one >> 24) as usize]
            ^ S8[3][(two & 0xff) as usize]
            ^ S8[2][((two >> 8) & 0xff) as usize]
            ^ S8[1][((two >> 16) & 0xff) as usize]
            ^ S8[0][(two >> 24) as usize];
        buf = buf.offset(8);
        len = len.wrapping_sub(8 as z_size_t);
    }

    if len != 0 {
        let tail = len as usize;
        // SAFETY: after the main loop, `buf` points to exactly `len` remaining bytes;
        // this local shared slice is used only for the byte tail walk and creates no
        // mutable aliases.
        let bytes = unsafe { core::slice::from_raw_parts(buf, tail) };
        for &b in bytes.iter() {
            c = crc_table[0][((c as c_uint ^ b as c_uint) & 0xff) as usize] ^ c >> 8;
        }
    }

    c = !c;
    c as c_ulong
}

